#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Run on the operator workstation, never with bash -x (secrets are read below).
umask 077
TOTAL_STAGES=6
CONFIG_DIR="${TAYYN_SETUP_DIR:-.local/production}"
mkdir -p "$CONFIG_DIR"
chmod 700 "$CONFIG_DIR"
ENV_FILE="$CONFIG_DIR/.production.env.incomplete"
if [[ -e "$CONFIG_DIR/production.env" || -e "$ENV_FILE" || -e "$CONFIG_DIR/monitor-secrets.json" || -e "$CONFIG_DIR/.monitor-secrets.json.incomplete" ]]; then
  warn "Configuration already exists. Keep it for updates; use TAYYN_SETUP_DIR for a separate new environment."
  exit 1
fi
# No partially entered credentials become a deployable configuration.
trap 'rm -f "$CONFIG_DIR/.production.env.incomplete" "$CONFIG_DIR/.monitor-secrets.json.incomplete"' EXIT
command -v python3 >/dev/null || { warn 'Python 3 is required.'; exit 1; }
# Only data is written; never source an env file or interpolate it as commands.
valid_value() {
  [[ -n "$2" && "$2" != *$'\n'* && "$2" != *$'\r'* && "$2" != *"'"* ]] || {
    warn "$1 must be nonempty, single-line, and contain no apostrophe."
    exit 1
  }
}
save_literal() { valid_value "$1" "$2"; write_env "$1" "'$2'"; chmod 600 "$ENV_FILE"; }
random_secret() { python3 -c 'import secrets; print(secrets.token_hex(32))'; }

banner "Tayyn Hyzmat production configuration"
note 'This setup saves only a completed run. If cancelled, start again; existing completed configuration is kept.'
stage "Namecheap domain"
open_url 'https://ap.www.namecheap.com/domains/list/'
step 'Choose your domain in Domain List → Manage → Advanced DNS.'
step 'Later, add A records for the app host to Standard L. Do not change MX/email records.'
ask DOMAIN 'Production app hostname, for example dispatch.example.com:'
DOMAIN=$(DOMAIN_VALUE="$DOMAIN" python3 -c 'import os,re; d=os.environ["DOMAIN_VALUE"].lower(); assert re.fullmatch(r"(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}",d), "Use a valid hostname without scheme/path"; print(d)')
save_literal DOMAIN "$DOMAIN"
save_literal CORS_ORIGIN "https://$DOMAIN,https://localhost,http://localhost,capacitor://localhost"
note 'Native localhost origins permit the packaged Android client. APK endpoints still need a production build.'

stage "Clean production admin"
ask SEED_ADMIN_PHONE 'Admin phone, e.g. +99365999999:'
[[ "$SEED_ADMIN_PHONE" =~ ^\+993[0-9]{8}$ ]] || { warn 'Use +993 followed by eight digits without spaces.'; exit 1; }
ask_secret SEED_ADMIN_PASSWORD 'New admin password (hidden, minimum 6 characters; use a unique production password):'
valid_value SEED_ADMIN_PASSWORD "$SEED_ADMIN_PASSWORD"
PASSWORD_VALUE="$SEED_ADMIN_PASSWORD" python3 -c 'import os; p=os.environ["PASSWORD_VALUE"]; assert len(p)>=6 and len(p.encode())<=72, "Password must be 6 characters to 72 UTF-8 bytes"'
save_literal SEED_ADMIN_PHONE "$SEED_ADMIN_PHONE"
save_literal SEED_ADMIN_PASSWORD "$SEED_ADMIN_PASSWORD"
save_literal POSTGRES_PASSWORD "$(random_secret)"
save_literal JWT_ACCESS_SECRET "$(random_secret)"
save_literal JWT_REFRESH_SECRET "$(random_secret)"
note 'This captures configuration only. Seeding is a separate, explicit first-install step.'

stage "HTTPS certificate paths"
step 'Obtain a trusted certificate for the production hostname and plan renewal before expiry.'
step 'The offline deployment uses supplied PEM files; it does not fetch certificates on the VPS.'
ask TLS_CERT_PATH 'Absolute certificate-chain path on Standard L (e.g. /etc/tayyn/tls/fullchain.pem):'
ask TLS_KEY_PATH 'Absolute private-key path on Standard L (e.g. /etc/tayyn/tls/privkey.pem):'
[[ "$TLS_CERT_PATH" == /* && "$TLS_KEY_PATH" == /* ]] || { warn 'Certificate paths must be absolute.'; exit 1; }
save_literal TLS_CERT_PATH "$TLS_CERT_PATH"
save_literal TLS_KEY_PATH "$TLS_KEY_PATH"

stage "Yandex and Firebase runtime credentials"
open_url 'https://developer.tech.yandex.ru/'
step 'Copy the production server geocoder key; check its actual source-IP restrictions.'
ask_secret YANDEX_GEOCODER_API_KEY 'Server Yandex geocoder key (hidden):'
save_literal YANDEX_GEOCODER_API_KEY "$YANDEX_GEOCODER_API_KEY"
write_env YANDEX_GEOCODER_DAILY_LIMIT 800
note '800 is the initial spend cap against the stated 1,000 allowance. Confirm the provider reset period before enabling automatic lookup.'
step 'Keep automatic geocoder access disabled until quota timezone/reset hour are confirmed in the provider console.'
note 'YANDEX_GEOCODER_QUOTA_TIMEZONE is intentionally unset, which disables the current backend geocoder.'
open_url 'https://console.firebase.google.com/'
step 'Production project → Project settings → Service accounts → generate a private key.'
step 'This is a server service-account JSON, not Android google-services.json.'
ask FIREBASE_FILE 'Path to the local Firebase service-account JSON:'
FIREBASE_SERVICE_ACCOUNT_JSON=$(python3 - "$FIREBASE_FILE" <<'PYJSON'
import json, sys
from pathlib import Path
value = json.loads(Path(sys.argv[1]).read_text())
if not all(value.get(k) for k in ('project_id', 'client_email', 'private_key')):
    raise SystemExit('Not a Firebase service-account credential')
print(json.dumps(value, separators=(',', ':')))
PYJSON
)
save_literal FIREBASE_SERVICE_ACCOUNT_JSON "$FIREBASE_SERVICE_ACCOUNT_JSON"
note 'The public browser Maps key is a build setting. It is configured separately when building the web image.'

stage "Resend delivery to Gmail"
open_url 'https://resend.com/domains'
step 'Add your sender domain in Resend; copy the exact DNS records it supplies into Namecheap Advanced DNS.'
step 'Verify those records in Resend. Preserve any existing MX/SPF records; avoid duplicate SPF records.'
ask RESEND_FROM 'Verified sender address (for example alerts@your-domain.tld):'
open_url 'https://resend.com/api-keys'
step 'Create an API key restricted to sending from the chosen domain.'
ask_secret RESEND_API_KEY 'Resend API key (hidden):'
valid_value RESEND_FROM "$RESEND_FROM"
[[ "$RESEND_FROM" =~ ^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$ ]] || { warn 'Enter a sender email address only.'; exit 1; }
valid_value RESEND_API_KEY "$RESEND_API_KEY"
export RESEND_FROM RESEND_API_KEY
MONITOR_SECRETS_PATH="$CONFIG_DIR/.monitor-secrets.json.incomplete" python3 - <<'PYJSON'
import json, os
from pathlib import Path
path = Path(os.environ['MONITOR_SECRETS_PATH'])
with path.open('x') as f:
    json.dump({'resend_api_key': os.environ['RESEND_API_KEY'],
               'resend_from': os.environ['RESEND_FROM'],
               'alert_email': 'bagtyyarkowusow.dev@gmail.com'}, f, indent=2)
path.chmod(0o600)
PYJSON
unset RESEND_API_KEY
say 'Monitoring secrets saved privately; no test email has been sent.'
note 'Monitor policy: initial healthy email; daily 09:00 Asia/Ashgabat; incident 0/5/15 then every 30 minutes; recovery email.'

stage "Transfer and launch checklist"
mv "$ENV_FILE" "$CONFIG_DIR/production.env"
ENV_FILE="$CONFIG_DIR/production.env"
mv "$CONFIG_DIR/.monitor-secrets.json.incomplete" "$CONFIG_DIR/monitor-secrets.json"
say "Private configuration directory: $CONFIG_DIR"
step 'Read docs/production-handoff.md and docs/offline-production-bundle.md before transferring files.'
step 'Transfer production.env to /etc/tayyn/app.env on Standard L using SSH/SFTP; chmod 600.'
step 'Transfer monitor-secrets.json only to /etc/tayyn/monitor-secrets.json on Standard S; chmod 600.'
step 'Configure operations.json from its role template, age public recipient, pinned SSH host key and recovery key stored offline.'
step 'Use the verified offline bundle, bootstrap only admin + canonical regions, and perform a disposable restore.'
step 'Verify HTTPS/WebSockets, Yandex authorization, physical-phone FCM and external outage alerts before opening service.'
warn 'Never commit this directory, copy it into images, or paste secrets into chat. This wizard does not install or deploy.'
finish
